for name, op in [("A", lambda A, B: A.extend(B)), ("B", lambda A, B: A.append(B)),
                 ("C", lambda A, B: A.update(B)), ("D", lambda A, B: A.insert(B))]:
    A = [1, 2, 3]
    B = [4, 5, 6]
    try:
        r = op(A, B)
        print(name, "A =", A, "| return value:", r, "| matches:", A == [1, 2, 3, 4, 5, 6])
    except Exception as e:
        print(name, type(e).__name__ + ":", e)
